from pathlib import Path
import base64,json,subprocess,time
pre=['runuser','-u','likimk','--','env','XDG_RUNTIME_DIR=/run/user/1602','DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1602/bus']
subprocess.run(pre+['systemctl','--user','stop','f8-sensor-relay.service'],check=True)
subprocess.run(['modprobe','-r','f8_sensor_relay'],check=True)
files={'usr/local/lib/f8-pro/sensor-relay.py': '', 'usr/local/lib/f8-pro/sensor-relay-panel.py': '', 'usr/lib/modules/6.1.115-vendor-rk35xx/extra/f8-pro/f8_sensor_relay.ko': '', 'usr/share/f8-pro/sensor-relay-r1/module-check.json': ''}
for name,data in files.items():(Path('/')/name).write_bytes(base64.b64decode(data))
subprocess.run(['depmod','-a'],check=True)
subprocess.run(['/usr/bin/python3','-I','/usr/libexec/f8-pro/sensor-relay-start.py'],check=True)
subprocess.run(['udevadm','settle'],check=True)
subprocess.run(pre+['systemctl','--user','start','f8-sensor-relay.service'],check=True)
time.sleep(3)
print(json.dumps({'snapshot':json.loads(Path('/run/user/1602/f8-sensor-relay.json').read_text()),'iio_devices':[{'path':str(p.resolve()),'name':(p/'name').read_text().strip()} for p in Path('/sys/bus/iio/devices').glob('iio:device*')]}))
